import os
import re
import json

# Load all demo pairs received so far for this task
d = os.environ['RLM_SESSION_DIR']
session_base = os.path.basename(d)
task_id = "task-ef8edfd1"

# Try to load the global session log that contains this instance's data
session_dir = os.path.join(d, '..', '..', 'sessions')
session_file = os.path.join(session_dir, session_base + '.jsonl')

try:
    with open(session_file, 'r') as f:
        content = f.read()

    # Find all demo pairs and input/output grids
    demos = []
    inputs = {}
    outputs = {}

    # Parse demo pairs
    lines = content.split('\n')
    current_section = None
    current_rows = []
    current_h = None
    current_w = None

    for line in lines:
        line_stripped = line.strip()
        if line_stripped.startswith('Demo pair '):
            # Check if this is input or output
            match = re.match(r'Demo pair \d+ (input|output) \((\d+)x(\d+)\):', line_stripped)
            if match:
                if current_section:
                    # Save previous
                    if current_h and current_w:
                        current_grid = [current_rows[i].split() for i in range(min(len(current_rows), int(current_h)))]
                        current_flat = current_grid[0]
                        while len(current_flat) < int(current_w):
                            current_flat.extend([0] * (int(current_w) - len(current_flat)))
                        current_grid = [current_flat[:int(current_w)] for _ in range(int(current_h))]
                    else:
                        current_grid = [[0]*int(current_w) for _ in range(int(current_h))]

                    demos.append({
                        'label': match.group(1).__startswith('input') or match.group(1).__startswith('output'),
                        'input_output': current_grid
                    })
                current_section = match.group(1)
                current_h, current_w = int(match.group(2)), int(match.group(3))
                current_rows = []
        elif line_stripped and current_section:
            current_rows.append(line_stripped)

    # Store task info
    task_info = {
        'task_id': task_id,
        'demos': demos,
        'files': [],
        'rule_status': 'unknown'
    }
    print(f"Found {len(demos)} pairs (input+output sections)")
    for d in demos[:20]:
        print(f"  Demo: {d['label']} {d['input_output'][0] if len(d['input_output']) > 0 else 'empty'}")
except Exception as e:
    print(f"Error loading sessions: {e}")

